// === Tab: sketch147268 ===

let NB_PARTICLES = 200;
ArrayList<Triangle> triangles;
let parts = new Array(NB_PARTICLES);
let image;
let myColor = new MyColor();

function setup()
{
  createCanvas(1280, 720);
  for (i = 0; i < NB_PARTICLES; i++)
  {
    parts[i] = new Particle();
  }
}

function draw()
{
  myColor.update();
  noStroke();
  fill(120, 1);
  background(0);
  triangles = new ArrayList<Triangle>();
  let p1, p2;

  for (i = 0; i < NB_PARTICLES; i++)
  {
    parts[i].move();
  }

  for (i = 0; i < NB_PARTICLES; i++)
  {
    p1 = parts[i];
    p1.neighboors = new ArrayList<Particle>();
    p1.neighboors.add(p1);
    for (j = i+1; j < NB_PARTICLES; j++)
    {
      p2 = parts[j];
      let d = PVector.dist(p1.pos, p2.pos); 
      if (d > 0 && d < Particle.DIST_MAX)
      {
        p1.neighboors.add(p2);
      }
    }
    if(p1.neighboors.size() > 1)
    {
      addTriangles(p1.neighboors);
    }
  }
  drawTriangles();
}

function drawTriangles()
{
  noStroke();
  fill(myColor.R, myColor.G, myColor.B, 5);
  stroke(max(myColor.R-15, 0), max(myColor.G-15, 0), max(myColor.B-15, 0), 13);
  //noFill();
  beginShape(TRIANGLES);
  for (i = 0; i < triangles.size(); i ++)
  {
    let t = triangles.get(i);
    t.display();
  }
  endShape();  
}

function addTriangles(ArrayList<Particle> p_neighboors)
{
  let s = p_neighboors.size();
  if (s > 3)
  {
    for (i = 1; i < s-1; i ++)
    { 
      for (j = i+1; j < s; j ++)
      { 
         triangles.add(new Triangle(p_neighboors.get(0).pos, p_neighboors.get(i).pos, p_neighboors.get(j).pos));
      }
    }
  }
}

function mousePressed()
{
   myColor.init(); 
}

class MyColor
{
  R, G, B, Rspeed, Gspeed, Bspeed;
  minSpeed = .7;
  maxSpeed = 1.5;
  constructor()
  {
    init();
  }

  function init()
  {
    R = random(255);
    G = random(255);
    B = random(255);
    Rspeed = (random(1) > .5 ? 1 : -1) * random(minSpeed, maxSpeed);
    Gspeed = (random(1) > .5 ? 1 : -1) * random(minSpeed, maxSpeed);
    Bspeed = (random(1) > .5 ? 1 : -1) * random(minSpeed, maxSpeed);
  }

  function update()
  {
    Rspeed = ((R += Rspeed) > 255 || (R < 0)) ? -Rspeed : Rspeed;
    Gspeed = ((G += Gspeed) > 255 || (G < 0)) ? -Gspeed : Gspeed;
    Bspeed = ((B += Bspeed) > 255 || (B < 0)) ? -Bspeed : Bspeed;
  }
}

class Particle
{
  RAD = 4;
  BOUNCE = -1;
  SPEED_MAX = 4.2;
  DIST_MAX = 100;
  let speed = new PVector(random(-SPEED_MAX, SPEED_MAX), random(-SPEED_MAX, SPEED_MAX));
  let acc = new PVector(0, 0);
  pos;
  //neighboors contains the particles within let distance, as well as itself
  ArrayList<Particle> neighboors;

  constructor()
  {
    pos = new PVector (random(width), random(height));
  }

  function move()
  {    
    pos.add(speed);

    acc.mult(0);

    if (pos.x < 0)
    {
      pos.x = 0;
      speed.x *= BOUNCE;
    }
    else if (pos.x > width)
    {
      pos.x = width;
      speed.x *= BOUNCE;
    }
    if (pos.y < 0)
    {
      pos.y = 0;
      speed.y *= BOUNCE;
    }
    else if (pos.y > height)
    {
      pos.y = height;
      speed.y *= BOUNCE;
    }
  }

  function display()
  {
    fill(255, 14);
    ellipse(pos.x, pos.y, RAD, RAD);
  }
}

class Triangle
{
  A, B, C; 

  constructor(p1, p2, p3)
  {
    A = p1;
    B = p2;
    C = p3;
  }

  function display()
  {
    vertex(A.x, A.y);
    vertex(B.x, B.y);
    vertex(C.x, C.y);
  }
}

